// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VerificationTasks) predicate.VerificationTasks {
	return predicate.VerificationTasks(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VerificationTasks) predicate.VerificationTasks {
	return predicate.VerificationTasks(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VerificationTasks) predicate.VerificationTasks {
	return predicate.VerificationTasks(sql.NotPredicates(p))
}
